SELECT *, CORR(quantity, unit_price) OVER (PARTITION BY product_id) AS corr_quantity_unit_price, AVG(unit_price) OVER (PARTITION BY order_id ORDER BY quantity ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS unit_price_avg_3_prior, MAX(unit_price) OVER (PARTITION BY order_id) AS order_id_max_unit_price, NTILE(3) OVER (PARTITION BY product_id, order_id ORDER BY quantity DESC, id ASC) AS quantity_bucket, NTILE(4) OVER w_running AS unit_price_bucket FROM order_items WINDOW w_running AS (PARTITION BY product_id ORDER BY unit_price ASC, id ASC)
